mapper.update:
UPDATE BOARD
SET BOARDTITLE   = #{boardTitle},
    BOARDCONTENT = #{boardContent}
WHERE BOARDID = #{boardId}

mapper.delete:
DELETE FROM COMMENTS_LIKE
WHERE COMMENTSID IN (
    SELECT COMMENTSID FROM COMMENTS WHERE BOARDID = #{boardId}
)

